  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "A morpholine-substituted heteroaromatic compound showed good-to-excellent CNS penetration with a brain-to-plasma Kp of 11.4 and negligible P-gp efflux in mice, directly supporting meaningful CNS access for the morpholine-containing heteroaromatic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "A morpholine-containing compound was rapidly distributed to the CNS in mice, reaching 773.6 ng/g in brain at Tmax, demonstrating that morpholine moieties do not preclude robust brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A CF3-substituted aromatic heteroaryl compound accumulated in mGluR2-rich brain regions in rat PET imaging, supporting brain penetration for the query's CF3/heteroaromatic framework.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "A CF3-containing heteroaromatic PET ligand showed high brain uptake and fast kinetics suitable for imaging in rodents and non-human primates, indicating that this combination of features is compatible with good CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Flucytosine, an amino-substituted heteroaromatic small molecule, rapidly penetrated the cerebrum in murine pharmacokinetic studies, supporting CNS access for amino-heteroaromatic chemotypes.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All highly transferable experimental analogues support meaningful CNS access: morpholine-containing heteroaromatics show high Kp and brain concentrations, CF3-heteroaromatics show PET-detectable brain uptake, and amino-heteroaromatic small molecules penetrate CSF/cerebrum. The query combines these favorable features, so the prediction is pass.",
